WITH cleaned AS (SELECT *, LAST_DAY(order_date) AS order_date_month_end, ROUND(discount / amount, 2) AS discount_per_amount, COALESCE(channel, 'N/A') AS channel_filled FROM orders WHERE status = 'RETURNED') SELECT CASE WHEN amount >= 1370 THEN 'HIGH' ELSE 'LOW' END AS amount_tier, CASE WHEN discount >= 0.36 THEN 'PREMIUM' ELSE 'STANDARD' END AS discount_tier, CASE WHEN shipping_fee >= 34 THEN 'PREMIUM' ELSE 'STANDARD' END AS shipping_fee_tier, COUNT(CASE WHEN channel = 'web' THEN 1 END) AS web_count, CORR(shipping_fee, discount) AS corr_shipping_fee_discount, COUNT(DISTINCT channel) AS distinct_channels, ROUND(AVG(discount), 2) AS avg_discount FROM cleaned GROUP BY 1, 2, 3 ORDER BY avg_discount DESC NULLS LAST;
